def proverb(*items, qualifier=None):
    if not items:
        return []

    lines = []
    for a, b in zip(items, items[1:]):
        lines.append(f"For want of a {a} the {b} was lost.")

    if qualifier:
        final = f"And all for the want of a {qualifier} {items[0]}."
    else:
        final = f"And all for the want of a {items[0]}."

    lines.append(final)
    return lines
